    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .project-name { overflow-wrap: anywhere; }
    .back { margin-bottom: 20px; background: #465365; }
    [hidden] { display: none !important; }
  </style>
</head>
<body>
  <main>
    <section id="list-view">
      <h1>Workboard</h1>
      <form id="create-form">
        <label for="project-name">Project name</label>
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </form>
      <p id="message" role="alert" aria-live="polite"></p>
      <div id="projects" aria-label="Projects"></div>
    </section>
    <section id="project-view" hidden>
      <button class="back" id="back-button" type="button">Projects</button>
      <h1 id="project-title"></h1>
    </section>
  </main>
  <script>
    const listView = document.querySelector('#list-view');
    const projectView = document.querySelector('#project-view');
    const projectList = document.querySelector('#projects');
    const message = document.querySelector('#message');

    function showList() {
      listView.hidden = false;
      projectView.hidden = true;
      document.title = 'Workboard';
      loadProjects();
    }

    async function openProject(id) {
      const response = await fetch(`/api/projects/${id}`);
      if (!response.ok) { history.replaceState({}, '', '/'); showList(); return; }
      const project = await response.json();
      document.querySelector('#project-title').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      listView.hidden = true;
      projectView.hidden = false;
    }

    async function loadProjects() {
      const response = await fetch('/api/projects');
      const projects = await response.json();
      projectList.replaceChildren();
      for (const project of projects) {
        const row = document.createElement('div');
        row.dataset.testid = 'project-row';
        row.className = 'project-row';
        const name = document.createElement('span');
        name.className = 'project-name';
        name.textContent = project.name;
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = 'Open project';
        button.addEventListener('click', () => {
          history.pushState({}, '', `/projects/${project.id}`);
          openProject(project.id);
        });
        row.append(name, button);
        projectList.append(row);
      }
    }

    document.querySelector('#create-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#project-name');
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ name: input.value })
      });
      if (!response.ok) {
        const result = await response.json();
        message.textContent = result.error || 'Project name is required';
        return;
      }
      message.textContent = '';
      input.value = '';
      await loadProjects();
    });

    document.querySelector('#back-button').addEventListener('click', () => {
      history.pushState({}, '', '/');
      showList();
    });
    addEventListener('popstate', () => {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      match ? openProject(match[1]) : showList();
    });
    const initial = location.pathname.match(/^\/projects\/(\d+)$/);
    initial ? openProject(initial[1]) : showList();
  </script>
</body>
</html>

